 while(current<target){lengths[grow[cursor++%grow.length]]+=4;current+=4}cursor=0;while(current>target&&cursor<80){const k=grow[cursor++%grow.length];if(lengths[k]>mins[k]){lengths[k]-=4;current-=4}}
