function updateSongMicClock(){if(!songMicActive)return;const sec=(performance.now()-songMicStarted)/1000,db=songMicLastLevel>0?20*Math.log10(songMicLastLevel):-90,pct=Math.max(0,Math.min(100,Math.round((db+60)/50*100)));$('#songMicLevelFill').style.width=pct+'%';$('#songMicLevelText').textContent=pct<4?'입력 없음':pct<20?'매우 작음':pct<45?'입력 확인':pct<78?'좋음':'너무 큼';$('#songMicStatus').textContent=`● 마이크 녹음 중 ${sec.toFixed(1)}초 · 입력 레벨 ${pct}%`;songMicTimer=requestAnimationFrame(updateSongMicClock)}
