async function startSongMic(){if(!navigator.mediaDevices?.getUserMedia)return toast('이 브라우저는 마이크 입력을 지원하지 않습니다');if(songMicActive)return;try{songMicStream=await openSongMicStream();songMicPcmChunks=[];songMicBlob=null;$('#songAudioFile').value='';const AC=window.AudioContext||window.webkitAudioContext;songMicAudioCtx=new AC();await songMicAudioCtx.resume?.();songMicSampleRate=songMicAudioCtx.sampleRate;songMicSourceNode=songMicAudioCtx.createMediaStreamSource(songMicStream);songMicAnalyser=songMicAudioCtx.createAnalyser();songMicAnalyser.fftSize=1024;songMicProcessor=songMicAudioCtx.createScriptProcessor?songMicAudioCtx.createScriptProcessor(4096,1,1):null;if(!songMicProcessor)throw new Error('PCM recorder unavailable');songMicSilentGain=songMicAudioCtx.createGain();songMicSilentGain.gain.value=0;songMicSourceNode.connect(songMicAnalyser);songMicSourceNode.connect(songMicProcessor);songMicProcessor.connect(songMicSilentGain).connect(songMicAudioCtx.destination);songMicProcessor.onaudioprocess=e=>{if(!songMicActive)return;const input=e.inputBuffer.getChannelData(0),copy=new Float32Array(input);songMicPcmChunks.push(copy);let sum=0;for(let i=0;i<input.length;i++)sum+=input[i]*input[i];songMicLastLevel=Math.sqrt(sum/input.length)};songMicActive=true;songMicStarted=performance.now();$('#startSongMic').disabled=true;$('#stopSongMic').disabled=false;$('#songMicLevelFill').style.width='0%';$('#songMicLevelText').textContent='입력 확인 중';$('#songMicStatus').textContent='● 마이크 녹음 중 0.0초';updateSongMicClock();toast('마이크 녹음을 시작했습니다. 아래 입력 레벨이 움직이는지 확인해 주세요')}catch(e){console.error(e);songMicActive=false;songMicStream?.getTracks().forEach(t=>t.stop());songMicStream=null;try{await songMicAudioCtx?.close()}catch{}songMicAudioCtx=null;$('#startSongMic').disabled=false;$('#stopSongMic').disabled=true;const msg=songMicErrorText(e);$('#songMicStatus').textContent=msg;toast(msg)}}
async function stopSongMic(){if(!songMicActive)return toast('지금 마이크로 녹음하고 있지 않습니다');songMicActive=false;cancelAnimationFrame(songMicTimer);$('#songMicStatus').textContent='WAV 녹음 파일을 만들고 있습니다…';$('#stopSongMic').disabled=true;try{songMicProcessor&&(songMicProcessor.onaudioprocess=null);songMicSourceNode?.disconnect();songMicProcessor?.disconnect();songMicAnalyser?.disconnect();songMicSilentGain?.disconnect();songMicStream?.getTracks().forEach(t=>t.stop());const samples=mergeFloat32Chunks(songMicPcmChunks),seconds=samples.length/Math.max(1,songMicSampleRate);if(samples.length<songMicSampleRate*.4)throw new Error('녹음 시간이 너무 짧습니다');songMicBlob=pcmToWavBlob(samples,songMicSampleRate);songMicName='마이크로 들은 노래.wav';setImportedAudioBlob(songMicBlob,songMicName);$('#songMicStatus').textContent=`마이크 녹음 완료 · ${seconds.toFixed(1)}초 · ${(songMicBlob.size/1024/1024).toFixed(1)}MB · 자동 분석 중…`;$('#songMicLevelFill').style.width='0%';$('#songMicLevelText').textContent='녹음 완료';await songMicAudioCtx?.close();songMicAudioCtx=null;songMicStream=null;$('#startSongMic').disabled=false;await analyzeImportedSong()}catch(e){console.error(e);$('#songMicStatus').textContent=`마이크 녹음을 저장하지 못했습니다: ${e?.message||'알 수 없는 오류'}`;$('#startSongMic').disabled=false;toast('마이크 녹음 저장에 실패했습니다')}}
